const string ProductionSchema="""CREATE TABLE IF NOT EXISTS ProductionTruthArtifacts(ProductionTruthArtifactId TEXT PRIMARY KEY,RunId TEXT NOT NULL UNIQUE,CompletionBindingId TEXT NOT NULL,ProductionRunId TEXT NOT NULL,ModelVersion TEXT NOT NULL,CalibrationVersion TEXT NOT NULL,CanonicalExecutionOptionsJson TEXT NOT NULL,ExecutionOptionsHash TEXT NOT NULL,CanonicalRequestJson TEXT NOT NULL,RequestHash TEXT NOT NULL,CanonicalResponseJson TEXT NOT NULL,ResponseHash TEXT NOT NULL,CheckpointsJson TEXT NOT NULL,MonthlyTruthJson TEXT NOT NULL,CreatedUtc TEXT NOT NULL,FOREIGN KEY(RunId)REFERENCES Runs(RunId));CREATE TABLE IF NOT EXISTS ProductionSeries(ProductionSeriesId TEXT PRIMARY KEY,RunId TEXT NOT NULL UNIQUE,ProductionTruthArtifactId TEXT NOT NULL,ProductionRunId TEXT NOT NULL,ModelVersion TEXT NOT NULL,CalibrationVersion TEXT NOT NULL,OptionsHash TEXT NOT NULL,CanonicalOptionsJson TEXT NOT NULL,CanonicalInputJson TEXT NOT NULL,InputHash TEXT NOT NULL,CanonicalOutputJson TEXT NOT NULL,OutputHash TEXT NOT NULL,MonthsJson TEXT NOT NULL,CheckpointsJson TEXT NOT NULL,WaterBreakthroughMonth INTEGER NULL,GasBreakthroughMonth INTEGER NULL,QcSummaryJson TEXT NOT NULL,CreatedUtc TEXT NOT NULL,FOREIGN KEY(RunId)REFERENCES Runs(RunId),FOREIGN KEY(ProductionTruthArtifactId)REFERENCES ProductionTruthArtifacts(ProductionTruthArtifactId));CREATE TRIGGER IF NOT EXISTS TR_ProductionTruth_NoUpdate BEFORE UPDATE ON ProductionTruthArtifacts BEGIN SELECT RAISE(ABORT,"Production truth immutable");END;CREATE TRIGGER IF NOT EXISTS TR_ProductionTruth_NoDelete BEFORE DELETE ON ProductionTruthArtifacts BEGIN SELECT RAISE(ABORT,"Production truth immutable");END;CREATE TRIGGER IF NOT EXISTS TR_ProductionSeries_NoUpdate BEFORE UPDATE ON ProductionSeries BEGIN SELECT RAISE(ABORT,"Production series immutable");END;CREATE TRIGGER IF NOT EXISTS TR_ProductionSeries_NoDelete BEFORE DELETE ON ProductionSeries BEGIN SELECT RAISE(ABORT,"Production series immutable");END;""";}







